from lib import *
S = SS('f80')
R = J('f80'); cc = R['conc']
steps = [
    step("扩展骨架:Hello 的构造不绑定 app,init_app(app) 才绑定;配置默认值用 app.config.setdefault 填(HELLO_GREETING=hello、HELLO_DSN=mem://default);状态放 app.extensions['hello']。同一个 hello 对象在应用 1 里得到 hello, Ann,在设了 HELLO_GREETING=你好 的应用 2 里得到 你好, Ann。对同一个应用重复 init_app 抛我们自己写的 RuntimeError;应用上下文之外、或没 init_app 的应用里使用,各给出明确的错误信息。", t=tl(S(1)), done=lidx(S(1), '应用 1', '应用 2', '默认值'), mark=lidx(S(1), '重复 init_app', '应用上下文之外', '没 init_app'), kv=KV([['构造', '不绑定 app'], ['init_app', 'setdefault 配置 + 写 app.extensions'], ['误用', '给出明确的 RuntimeError']], ['init_app'])),
    step("扩展在 init_app 里顺手注册的东西都生效了:模板过滤器 shout('hey') 渲染成 HEY!;after_request 给每个响应加 X-Hello: hello;app.cli.add_command 加的 flask hello Bob 输出 hello, Bob (cli)(退出码 0),flask --help 的 Commands 里有 hello。同一份 --help 里还有 limiter——那是 Flask-Limiter 通过 Python 的入口点(entry point)自己注册的命令,不是我们的。", t=tl(S(2)), done=lidx(S(2), 'shout', 'X-Hello', 'flask hello Bob'), mark=lidx(S(2), 'Commands'), kv=KV([['模板过滤器', 'app.template_filter'], ['每个响应的头', 'app.after_request'], ['命令行', 'app.cli.add_command']], ['命令行'])),
    step(f"每个请求一个连接:懒创建(第一次访问 hello.conn 才创建,存在 g 里)、请求结束时在 teardown_appcontext 里关闭。5 个请求(2 个不用连接、3 个用)后 opened={R['conn'][0]} closed={R['conn'][1]};视图抛异常、HTTP 500 的请求,teardown 照样执行(opened={R['conn_err'][1]} closed={R['conn_err'][2]})。", t=tl(S(3)), done=lidx(S(3), '5 个请求', '视图抛异常'), kv=KV([['懒创建', '不用就不开'], ['teardown_appcontext', '正常与异常都会执行']], ['teardown_appcontext'])),
    step(f"状态放哪里:把当前值存在扩展对象的实例属性上(Bad),8 个并发请求各睡 0.2 秒再读自己写的值,有 {cc['bad']} 个读到了别人的值;存在 g 上(Good)则是 {cc['good']} 个。扩展对象是进程里所有请求共享的,请求相关的状态必须放在上下文里。", b=bars([['实例属性(Bad)', cc['bad'], f"{cc['bad']} / 8"], ['g(Good)', cc['good'], f"{cc['good']} / 8"]], 8, mark=[0], done=[1]), t=tl(S(4)), mark=lidx(S(4), 'bad'), done=lidx(S(4), 'good'), kv=KV([['扩展对象上的属性', '所有请求共享,会串'], ['g / app.extensions', '按请求 / 按应用隔离']], ['扩展对象上的属性'])),
    step("配置优先级是扩展作者自己约定的,这里的约定是 构造参数 > app.config > 默认值:构造参数 greeting='ctor' 加 HELLO_GREETING='cfg' → ctor;只有 HELLO_GREETING → cfg;都没设 → hello。要把这个约定写进文档,别让使用者去猜。", t=tl(S(5)), done=lidx(S(5), 'ctor', 'cfg', '都没设'), kv=KV([['优先级', '构造参数 > app.config > 默认值']], ['优先级'])),
    step("测试扩展:用工厂给每个用例一个全新的应用(3 个应用分别用 g0、g1、g2,响应互相独立)。但类属性计数器 FakeConn.opened 是进程级的共享状态,会让用例互相污染,每个用例开始前要清零——这一点最好在设计上避免(状态放在 app.extensions 或 g 里)。", t=tl(S(6)), done=lidx(S(6), '3 个互相独立'), mark=lidx(S(6), '共享的状态'), kv=KV([['工厂', '每个用例一个新应用'], ['类属性计数器', '会跨用例泄漏']], ['类属性计数器'])),
]
A = mkartf('f80', 80, 'Flask,自定义扩展,init_app,teardown,真实验证,动画演示',
    f'亲手写一个遵守约定的 Flask 扩展并逐项验证:init_app 与 app.extensions、配置默认值与优先级、顺手注册模板过滤器 after_request 与命令行、用 g 懒创建连接并在 teardown 里关闭、状态放扩展对象上 8 个并发请求有 {cc["bad"]} 个串数据而放 g 上是 {cc["good"]} 个。',
    '自己写 Flask 扩展要遵守哪些约定?连接之类的请求级资源放哪、怎么关?状态为什么不能放在扩展对象上?这篇写一个完整的最小扩展,每条约定都跑一遍。',
    [(f'{cc["bad"]} / 8', '状态存在扩展对象的实例属性上时,8 个并发请求读到别人值的个数'), ('3 个', '一个请求用一个懒创建的连接,请求结束时 teardown 关闭——5 个请求(3 个用连接)开关次数'), ('4 件事', 'init_app 里常做的:写默认配置、登记 app.extensions、注册钩子、注册命令')],
    [('扩展骨架', '<p>上一篇:<a href="flask-flask-cors.html">Flask-CORS</a>;下一篇:<a href="flask-flask-sqlalchemy-init.html">Flask-SQLAlchemy 初始化过程</a>。</p><p>第 71 篇讲了 init_app 的时机,这一篇把约定落成代码。</p>'), ('顺手注册的东西', None), ('请求级资源与 teardown', None), ('状态放哪里', '<p>并发请求用的是 gunicorn 的 gthread worker(每个请求一个线程)。</p>'), ('配置优先级', None), ('测试扩展', None)],
    steps, [ENV_F + '。扩展是本篇自己写的 hello_ext.py,连接是一个假的 FakeConn 计数对象', '没有验证:打包发布到 PyPI(pyproject 与入口点)、Flask 扩展命名规范的审核流程、异步视图(async def)里使用 g 的行为(见第 136 篇)、signals(blinker)的使用'], '自定义 Flask Extension', panels=[('t', 'term', '实验输出'), ('b', 'bars', '数量'), ('kv', 'kv', '要点')])
